"/\");\n  };\n  const vmFile=async(rel,b64)=>{\n    try{\n      const r=await fetch(API_BASE+\"/api/agent/file?path=\"+encodeURIComponent(rel)+(b64?\"&format=base64\":\"\"),{headers:agtHeaders()});\n      const j=await r.json();\n      return j.ok?String(j.content||\"\"):null;\n    }catch(e){ return null; }\n  };\n  for(const link of [...doc.querySelectorAll('link[rel=\"stylesheet\"][href]')]){\n    const href=link.getAttribute(\"href\")||\"\";\n    if(/^(https?:|data:|blob:)/i.test(href)) continue;\n    const css=await vmFile(norm(href),false);\n    if(css!==null){ const st=doc.createElement(\"style\"); st.textContent=css; link.replaceWith(st); }\n  }\n  for(const sc of [...doc.querySelectorAll(\"script[src]\")]){\n    const src=sc.getAttribute(\"src\")||\"\";\n    if(/^(https?:|data:|blob:)/i.test(src)) continue;\n    const js=await vmFile(norm(src),false);\n    if(js!==null){ const ns=doc.createElement(\"script\"); ns.textContent=js; sc.replaceWith(ns); }\n  }\n  for(const im of [...doc.querySelectorAll(\"img[src]\")]){\n    const src=im.getAttribute(\"src\")||\"\";\n    if(/^(https?:|data:|blob:)/i.test(src)) continue;\n    const b=await vmFile(norm(src),true);\n    if(b!==null){\n      const e2=(src.split(\".\").pop()||\"png\").toLowerCase();\n      im.setAttribute(\"src\",\"data:image/\"+(e2===\"svg\"?\"svg+xml\":(e2===\"jpg\"?\"jpeg\":e2))+\";base64,\"+b);\n    }\n  }\n  return LT+\"!DOCTYPE html\"+GT+\"\\n\"+doc.documentElement.outerHTML;\n}\n\n/* Exécution JS locale : iframe jetable, sandbox allow-scripts SEUL (pas de\n   same-origin), console capturée via postMessage et affichée. */\nfunction agtJsRun(code,out){\n  out.hidden=false;\n  out.textContent=\"Exécution…\";\n  const lines=[];\n  /* Balises construites par concaténation : la séquence fermante n'apparaît\n     JAMAIS littéralement dans le source (sinon le navigateur — ou un transit\n     qui mange les antislashs — referme le bloc de script de l'application). */\n  const T_OPEN=\"<\"+\"script>\", T_CLOSE=\"<\"+\"/\"+\"script>\";\n  const harness=LT+\"!DOCTYPE html\"+GT+LT+\"html\"+GT+LT+\"head\"+GT+LT+'meta charset=\"utf-8\"'+GT+LT+SL+\"head\"+GT+LT+\"body\"+GT+T_OPEN\n    +'(function(){var send=function(lvl,args){try{parent.postMessage({__agt:1,lvl:lvl,text:Array.prototype.map.call(args,function(a){try{return typeof a===\"string\"?a:JSON.stringify(a)}catch(e){return String(a)}}).join(\" \")},\"*\")}catch(e){}};'\n    +'[\"log\",\"info\",\"warn\",\"error\",\"debug\"].forEach(function(k){console[k]=function(){send(k===\"error\"?\"error\":\"log\",arguments)}});'\n    +'window.onerror=function(m){send(\"error\",[String(m)])};'\n    +'window.addEventListener(\"unhandledrejection\",function(e){send(\"error\",[String(e&&e.reason)])});})();'\n    +T_CLOSE+T_OPEN+'try{\\n'+String(code)+'\\n}catch(e){parent.postMessage({__agt:1,lvl:\"error\",text:String(e&&e.message||e)},\"*\")}'\n    +'parent.postMessage({__agt:1,done:1},\"*\");'+T_CLOSE+LT+SL+\"body\"+GT+LT+SL+\"html\"+GT;\n  const f=document.createElement(\"iframe\");\n  f.setAttribute(\"sandbox\",\"allow-scripts\");\n  f.style.display=\"none\";\n  let done=false;\n  const paint=()=>{ out.textContent=lines.length?lines.join(\"\\n\"):\"(aucune sortie)\"; };\n  const onMsg=(e)=>{\n    const d=e.data;\n    if(!d||!d.__agt||done) return;\n    if(d.done){ finish(); return; }\n    lines.push((d.lvl===\"error\"?\"⚠ \":\"\")+String(d.text));\n    paint();\n  };\n  const finish=()=>{\n    if(done) return;\n    done=true;\n    clearTimeout(to);\n    window.removeEventListener(\"message\",onMsg);\n    if(f.parentNode) f.parentNode.removeChild(f);\n    paint();\n  };\n  window.addEventListener(\"message\",onMsg);\n  const to=setTimeout(()=>{ lines.push(\"⏱ (arrêt après 10 s)\"); finish(); },10000);\n  /* srcdoc et non blob: : une iframe sandboxée (origine opaque) refuse de\n     charger une URL blob créée par la page — le script ne s'exécutait pas. */\n  f.srcdoc=harness;\n  (document.getElementById(\"avBody\")||document.body).appendChild(f);\n}\n\n/* « Lancer sur la VM » : le code est écrit dans ~/.agtconv puis exécuté via\n   le terminal de la VM (node/python3/bash) ; la sortie est renvoyée.\n   Python : matplotlib en Agg, la dernière figure est renvoyée en PNG. */\nasync function agtRunOnVm(lang,code,out,btn){\n  out.hidden=false;\n  out.textContent=\"Exécution sur la VM…\";\n  if(btn) btn.disabled=true;\n  try{\n    const id=Date.now()+\"_\"+Math.floor(Math.random()*1e6);\n    let src=String(code==null?\"\":code);\n    const ext=lang===\"js\"?\"js\":(lang===\"py\"?\"py\":\"sh\");\n    const fileAbs=\"/home/kasm-user/.agtconv/run_\"+id+\".\"+ext;\n    if(lang===\"py\"){\n      /* matplotlib est OPTIONNEL : sans lui, le script doit quand même\n         s'exécuter (l'import faisait échouer tout le programme). */\n      src='try:\\n    import matplotlib\\n    matplotlib.use(\"Agg\")\\nexcept Exception:\\n    pass\\n'+src\n        +'\\ntry:\\n'\n        +'    import matplotlib.pyplot as _plt, base64 as _b64, io as _io\\n'\n        +'    _figs=_plt.get_fignums()\\n'\n        +'    if _figs:\\n'\n        +'        _buf=_io.BytesIO()\\n'\n        +'        _plt.figure(_figs[-1]).savefig(_buf, format=\"png\", dpi=110, bbox_inches=\"tight\")\\n'\n        +'        print(\"AGT_IMG:\"+_b64.b64encode(_buf.getvalue()).decode())\\n'\n        +'except Exception:\\n    pass\\n';\n    }\n    const runner=lang===\"js\"\n      ? 'NODE=$(ls /home/kasm-user/.nvm/versions/node/*/bin/node 2>/dev/null | sort -V | tail -1); if [ -n \"$NODE\" ]; then timeout 170 \"$NODE\" \"'+fileAbs+'\"; else echo \"(Node indisponible sur la VM)\"; fi'\n      : (lang===\"py\" ? 'python3 \"'+fileAbs+'\"' : 'bash \"'+fileAbs+'\"');\n    const b64=agtB64Utf8(src);\n    const cmd=\"mkdir -p /home/kasm-user/.agtconv && printf '%s' '\"+b64+\"' | base64 -d > \"+fileAbs\n      +\" && cd /home/kasm-user && \"+(lang===\"js\"?\"\":\"timeout 170 \")+runner+\" 2>&1; rm -f \"+fileAbs;\n    const r=await fetch(API_BASE+\"/api/agent/exec\",{\n      method:\"POST\",headers:agtHeaders({\"Content-Type\":\"application/json\"}),\n      body:JSON.stringify({command:cmd,timeout:180})\n    });\n    const j=await r.json();\n    let so=String(j.stdout||\"\");\n    const se=String(j.stderr||\"\");\n    /* Node n'est pas installé sur la VM : on exécute le JS localement. */\n    if(lang===\"js\" && /Node indisponible/.test(so+se)){\n      out.textContent=\"\";\n      agtJsRun(code,out);\n      return;\n    }\n    let img=null;\n    const m=so.match(/AGT_IMG:([A-Za-z0-9+/=]+)/);\n    if(m){ img=m[1]; so=so.replace(/AGT_IMG:[A-Za-z0-9+/=]+/g,\"\").trim(); }\n    out.innerHTML=\"\";\n    if(img){\n      const im=document.createElement(\"img\");\n      im.className=\"av-runimg\";\n      im.src=\"data:image/png;base64,\"+img;\n      out.appendChild(im);\n    }\n    const tx=document.createElement(\"div\");\n    tx.textContent=(so||se||\"(aucune sortie)\")+(j.exit_code?\"  [exit \"+j.exit_code+\"]\":\"\");\n    out.appendChild(tx);\n  }catch(e){\n    out.textContent=\"Exécution impossible : \"+String(e&&e.message||e);\n  }finally{\n    if(btn) btn.disabled=false;\n  }\n}\n\n/* Présentation (pptx/ppt) : convertie en PDF par LibreOffice dans la VM,\n   puis affichée. Repli : message + téléchargement. */\nasync function agtPptxToPdf(path,name,content,body,mkBtn,dlBtn){\n  const div=document.createElement(\"div\"); div.className=\"av-md\";\n  body.appendChild(div);\n  div.innerHTML='<div class=\"at-load\">Conversion de la présentation via la VM…</div>';\n  const abs=\"/home/kasm-user/\"+String(path).replace(/^[/]+/,\"\");\n  if(!/['\"]/.test(abs)){\n    const outdir=\"/home/kasm-user/.agtconv\";\n    const base=name.replace(/\\.[^.]+$/,\"\")+\".pdf\";\n    try{\n      const er=await fetch(API_BASE+\"/api/agent/exec\",{\n        method:\"POST\",headers:agtHeaders({\"Content-Type\":\"application/json\"}),\n        body:JSON.stringify({timeout:180,command:\"mkdir -p \"+outdir+\" && rm -f \"+outdir+\"/*\"\n          +\" && (which soffice >/dev/null 2>&1 || sudo -n apt-get install -y -qq --no-install-recommends libreoffice-impress libreoffice-writer >/dev/null 2>&1);\"\n          +\" LD_LIBRARY_PATH=/usr/lib/libreoffice/program timeout 170 soffice --headless -env:UserInstallation=file:///tmp/lo_agt --convert-to pdf --outdir \"+outdir+\" '\"+abs+\"' >/dev/null 2>&1;\"\n          +\" [ -s '\"+outdir+\"/\"+base+\"' ] && echo OKPDF || echo NOPDF\"})\n      });\n      const jr=await er.json();\n      if(String(jr.stdout||\"\").includes(\"OKPDF\")){\n        const r2=await fetch(API_BASE+\"/api/agent/file?path=\"+encodeURIComponent(\".agtconv/\"+base)+\"&format=base64\",{headers:agtHeaders()});\n        const j2=await r2.json();\n        if(j2.ok){\n          const f=document.createElement(\"iframe\"); f.className=\"av-frame\";\n          const u=agtBlobUrl(agtB64Blob(j2.content,\"application/pdf\"));\n          f.src=u;\n          body.innerHTML=\"\"; body.appendChild(f);\n          dlBtn(u,base);\n          return;\n        }\n      }\n    }catch(e){}\n  }\n  div.innerHTML='<p>Conversion de la présentation impossible (LibreOffice indisponible sur la VM pour le moment). Utilisez le bouton Télécharger pour l’ouvrir sur votre appareil.</p>';\n}\n\nasync function agtOpenFile(path, name){\n  const title=document.getElementById(\"avTitle\");\n  const body=document.getElementById(\"avBody\");\n  const bar=document.getElementById(\"avBtns\");\n  title.textContent=name;\n  bar.innerHTML=\"\";\n  body.innerHTML='<div class=\"at-load\">Chargement…</div>';\n  agtRevBlobs();\n  agtViewer.hidden=false;\n  const ext=(name.split(\".\").pop()||\"\").toLowerCase();\n  const cat=agtCat(ext);\n  const needB64=(cat===\"img\"||cat===\"svg\"||cat===\"vid\"||cat===\"aud\"||cat===\"pdf\"||cat===\"docx\"||cat===\"pptx\"||cat===\"xlsx\");\n  let j={};\n  try{\n    const r=await fetch(API_BASE+\"/api/agent/file?path=\"+encodeURIComponent(path)+(needB64?\"&format=base64\":\"\"),{headers:agtHeaders()});\n    j=await r.json();\n  }catch(e){ j={ok:false}; }\n  if(!j.ok){ body.innerHTML='<div class=\"at-load\">Fichier illisible</div>'; return; }\n  let content=String(j.content==null?\"\":j.content);\n  const mkBtn=(label,fn)=>{\n    const b=document.createElement(\"button\");\n    b.type=\"button\"; b.className=\"av-btn\"; b.textContent=label;\n    b.addEventListener(\"click\",()=>{ fn(b); });\n    bar.appendChild(b);\n    return b;\n  };\n  const dlBtn=(url,fname)=>mkBtn(\"Télécharger\",()=>{\n    const a=document.createElement(\"a\"); a.href=url; a.download=fname; a.click();\n  });\n  const codeToggle=(mainEl,content2)=>{\n    const code=document.createElement(\"div\");\n    code.className=\"av-code\";\n    code.innerHTML=agtHighlight(content2);\n    code.hidden=true;\n    body.appendChild(code);\n    let showCode=false;\n    mkBtn(\"Voir le code\",(b)=>{\n      showCode=!showCode;\n      mainEl.hidden=showCode; code.hidden=!showCode;\n      b.classList.toggle(\"pressed\",showCode);\n      b.textContent=showCode?\"Aperçu\":\"Voir le code\";\n    });\n  };\n  body.innerHTML=\"\";\n  if(path===AGENT_USER+\"/user.md\"){\n    /* Fiche utilisateur : seul fichier modifiable depuis l'interface. */\n    agtRenderUserMd(content);\n    return;\n  }\n  if(cat===\"img\"){\n    /* Taille d'origine : aucune mise à l'échelle, la zone défile. */\n    const wrap=document.createElement(\"div\"); wrap.className=\"av-imgwrap\";\n    const im=document.createElement(\"img\"); im.className=\"av-img\"; im.alt=name;\n    im.src=\"data:image/\"+(ext===\"jpg\"?\"jpeg\":(ext===\"ico\"?\"x-icon\":ext))+\";base64,\"+content;\n    wrap.appendChild(im);\n    body.appendChild(wrap);\n    dlBtn(im.src,name);\n    return;\n  }\n  if(cat===\"svg\"){\n    /* Le fichier arrive en base64 : il est DÉCODÉ en texte d'abord.\n       (Avant, le base64 brut partait dans l'iframe -> aperçu blanc, et\n       « Voir le code » affichait du base64.) */\n    const text=agtDecodeUtf8(content);\n    const f=document.createElement(\"iframe\");\n    f.className=\"av-frame\";\n    f.setAttribute(\"sandbox\",\"allow-scripts\");\n    f.srcdoc=svgDoc(text);\n    body.appendChild(f);\n    codeToggle(f,text);\n    dlBtn(agtBlobUrl(new Blob([text],{type:\"image/svg+xml\"})),name);\n    mkBtn(\"Copier\",()=>agtCopyText(text));\n    return;\n  }\n  if(cat===\"vid\"){\n    const wrap=document.createElement(\"div\"); wrap.className=\"av-vidwrap\";\n    const v=document.createElement(\"video\"); v.className=\"av-vid\"; v.controls=true;\n    const u=agtBlobUrl(agtB64Blob(content,\"video/\"+(ext===\"mov\"?\"quicktime\":ext)));\n    v.src=u;\n    wrap.appendChild(v);\n    body.appendChild(wrap);\n    dlBtn(u,name);\n    return;\n  }\n  if(cat===\"aud\"){\n    const wrap=document.createElement(\"div\"); wrap.className=\"av-audwrap\";\n    const lab=document.createElement(\"div\"); lab.className=\"av-audname\"; lab.textContent=name;\n    const a=document.createElement(\"audio\"); a.className=\"av-aud\"; a.controls=true;\n    const u=agtBlobUrl(agtB64Blob(content,\"audio/\"+(ext===\"m4a\"?\"mp4\":(ext===\"oga\"?\"ogg\":ext))));\n    a.src=u;\n    wrap.appendChild(lab); wrap.appendChild(a);\n    body.appendChild(wrap);\n    dlBtn(u,name);\n    return;\n  }\n  if(cat===\"pdf\"){\n    /* Rendu CANVAS via pdf.js : une iframe PDF reste blanche sur de\n       nombreux navigateurs (Android, Firefox…), d'où « page blanche ». */\n    const u=agtBlobUrl(agtB64Blob(content,\"application/pdf\"));\n    dlBtn(u,name);\n    const wrap=document.createElement(\"div\"); wrap.className=\"av-pdfwrap\";\n    body.appendChild(wrap);\n    if(window.pdfjsLib&&window.pdfjsLib.getDocument){\n      wrap.innerHTML='<div class=\"at-load\">Rendu du PDF…</div>';\n      try{\n        try{ window.pdfjsLib.GlobalWorkerOptions.workerSrc=\"https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/legacy/build/pdf.worker.min.js\"; }catch(e2){}\n        const data=agtB64Blob(content,\"application/pdf\").arrayBuffer();\n        const doc=await window.pdfjsLib.getDocument({data:new Uint8Array(data),disableAutoFetch:true}).promise;\n        wrap.innerHTML=\"\";\n        const total=Math.min(doc.numPages,60);\n        for(let n=1;n<=total;n++){\n          const page=await doc.getPage(n);\n          const vp=page.getViewport({scale:1.6});\n          const cv=document.createElement(\"canvas\");\n          cv.className=\"av-pdfpage\";\n          cv.width=Math.round(vp.width); cv.height=Math.round(vp.height);\n          const cx=cv.getContext(\"2d\");\n          await page.render({canvasContext:cx,viewport:vp}).promise;\n          wrap.appendChild(cv);\n        }\n        if(doc.numPages>total){\n          const note=document.createElement(\"p\");\n          note.className=\"av-pdfnote\";\n          note.textContent=\"Affichage limité aux \"+total+\" premières pages (\"+doc.numPages+\" au total).\";\n          wrap.appendChild(note);\n        }\n      }catch(e){\n        wrap.innerHTML=\"<p>Aperçu du PDF indisponible ici. \"\n          +\"Utilisez le bouton Télécharger (le PDF est intact).</p>\";\n      }\n    }else{\n      wrap.innerHTML=\"<p>Aperçu du PDF indisponible (librairie de rendu non chargée). \"\n        +\"Utilisez le bouton Télécharger pour l’ouvrir sur votre appareil.</p>\";\n    }\n    return;\n  }\n  if(cat===\"docx\"){\n    const u=agtBlobUrl(agtB64Blob(content,\"application/vnd.openxmlformats-officedocument.wordprocessingml.document\"));\n    dlBtn(u,name);\n    const div=document.createElement(\"div\"); div.className=\"av-md av-docx\";\n    body.appendChild(div);\n    /* docx-preview respecte la mise en page ET les couleurs du document Word\n       (mammoth, lui, ne rendait qu'un texte gris, sans styles). */\n    if(window.docx&&window.docx.renderAsync){\n      div.innerHTML='<div class=\"at-load\">Mise en page du document Word…</div>';\n      try{\n        const blob=agtB64Blob(content,\"application/vnd.openxmlformats-officedocument.wordprocessingml.document\");\n        div.innerHTML=\"\";\n        await window.docx.renderAsync(blob, div, null,\n          {className:\"docx\",inWrapper:true,breakPages:true,ignoreLastRenderedPageBreak:true});\n        div.style.background=\"#fff\";\n      }catch(e){ div.innerHTML=\"<p>Document Word illisible.</p>\"; }\n    }else if(window.mammoth&&window.mammoth.convertToHtml){\n      div.innerHTML='<div class=\"at-load\">Conversion du document Word…</div>';\n      try{\n        const ab=await agtB64Blob(content,\"\").arrayBuffer();\n        const res=await window.mammoth.convertToHtml({arrayBuffer:ab});\n        div.innerHTML=res.value||\"<p>(document vide)</p>\";\n      }catch(e){ div.innerHTML=\"<p>Document Word illisible.</p>\"; }\n    }else{\n      div.innerHTML=\"<p>Aperçu Word indisponible ici (librairie de conversion non chargée). Utilisez le bouton Télécharger pour l’ouvrir sur votre appareil.</p>\";\n    }\n    return;\n  }\n  if(cat===\"pptx\"){\n    const u=agtBlobUrl(agtB64Blob(content,\"application/vnd.openxmlformats-officedocument.presentationml.presentation\"));\n    dlBtn(u,name);\n    await agtPptxToPdf(path,name,content,body,mkBtn,dlBtn);\n    return;\n  }\n  if(cat===\"xlsx\"){\n    const u=agtBlobUrl(agtB64Blob(content,\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\"));\n    dlBtn(u,name);\n    const div=document.createElement(\"div\"); div.className=\"av-md\";\n    body.appendChild(div);\n    if(window.XLSX&&window.XLSX.read){\n      div.innerHTML='<div class=\"at-load\">Lecture du tableur…</div>';\n      try{\n        const ab=await agtB64Blob(content,\"\").arrayBuffer();\n        const wb=window.XLSX.read(new Uint8Array(ab),{type:\"array\"});\n        let h=\"\";\n        wb.SheetNames.slice(0,4).forEach(sn=>{\n          h+=\"<h3>\"+esc(sn)+\"</h3>\"+window.XLSX.utils.sheet_to_html(wb.Sheets[sn]);\n        });\n        div.innerHTML=h||\"<p>(tableur vide)</p>\";\n      }catch(e){ div.innerHTML=\"<p>Tableur illisible.</p>\"; }\n    }else{\n      div.innerHTML=\"<p>Aperçu tableur indisponible ici (librairie non chargée). Utilisez le bouton Télécharger.</p>\";\n    }\n    return;\n  }\n  if(cat===\"html\"){\n    /* Le HTML lié à ses .css/.js locaux : fichiers frères inlinés depuis la VM. */\n    let full=content;\n    try{ full=await agtInlineHtml(path,content); }catch(e){}\n    const f=document.createElement(\"iframe\");\n    f.className=\"av-frame\";\n    f.setAttribute(\"sandbox\",\"allow-scripts allow-forms allow-modals allow-popups\");\n    /* srcdoc : les blob: ne se chargent pas dans une iframe sandboxée\n       (origine opaque) — l'aperçu restait donc vide. */\n    f.srcdoc=full;\n    body.appendChild(f);\n    codeToggle(f,content);\n    mkBtn(\"Copier le code\",()=>agtCopyText(content));\n    return;\n  }\n  if(cat===\"md\"){\n    const div=document.createElement(\"div\");\n    div.className=\"av-md\";\n    div.innerHTML=renderMarkdown(content);\n    agtKatex(div);\n    const pre=document.createElement(\"pre\");\n    pre.className=\"av-pre\"; pre.textContent=content; pre.hidden=true;\n    body.appendChild(div); body.appendChild(pre);\n    let raw=false;\n    mkBtn(\"Texte brut\",(b)=>{\n      raw=!raw;\n      div.hidden=raw; pre.hidden=!raw;\n      b.classList.toggle(\"pressed\",raw);\n      b.textContent=raw?\"Aperçu\":\"Texte brut\";\n    });\n    mkBtn(\"Copier\",()=>agtCopyText(content));\n    return;\n  }\n  if(cat===\"tex\"){\n    const div=document.createElement(\"div\");\n    div.className=\"av-md\";\n    let rendered=false;\n    if(window.renderMathInElement){\n      try{\n        const holder=document.createElement(\"div\");\n        holder.textContent=\"$$\"+content+\"$$\";\n        div.appendChild(holder);\n        window.renderMathInElement(div,{delimiters:[{left:\"$$\",right:\"$$\",display:true}],throwOnError:false});\n        rendered=true;\n      }catch(e){ rendered=false; }\n    }\n    if(!rendered){\n      div.innerHTML='<p class=\"um-zh\">Aperçu LaTeX indisponible ici (KaTeX non chargé) — voir le texte brut.</p>';\n    }\n    const pre=document.createElement(\"pre\");\n    pre.className=\"av-pre\"; pre.textContent=content;\n    pre.hidden=rendered; div.hidden=!rendered;\n    body.appendChild(div); body.appendChild(pre);\n    let raw=!rendered;\n    mkBtn(\"Texte brut\",(b)=>{\n      raw=!raw;\n      div.hidden=raw; pre.hidden=!raw;\n      b.classList.toggle(\"pressed\",raw);\n      b.textContent=raw?\"Aperçu\":\"Texte brut\";\n    });\n    mkBtn(\"Copier\",()=>agtCopyText(content));\n    return;\n  }\n  if(cat===\"js\"||cat===\"py\"||cat===\"sh\"){\n    const pre=document.createElement(\"pre\");\n    pre.className=\"av-pre\";\n    pre.innerHTML=agtHighlight(content);\n    const out=document.createElement(\"pre\");\n    out.className=\"av-run\"; out.hidden=true;\n    body.appendChild(pre); body.appendChild(out);\n    if(cat===\"js\"){\n      mkBtn(\"Exécuter\",()=>agtJsRun(content,out));\n      mkBtn(\"Lancer sur la VM\",(b)=>agtRunOnVm(\"js\",content,out,b));\n    }else if(cat===\"py\"){\n      mkBtn(\"Lancer sur la VM\",(b)=>agtRunOnVm(\"py\",content,out,b));\n    }else{\n      mkBtn(\"Lancer sur la VM\",(b)=>agtRunOnVm(\"sh\",content,out,b));\n    }\n    mkBtn(\"Copier\",()=>agtCopyText(content));\n    return;\n  }\n  if(content.length>200000){\n    content=content.slice(0,200000)+\"\\n\\n… [fichier trop volumineux — affichage tronqué]\";\n  }\n  const pre=document.createElement(\"pre\");\n  pre.className=\"av-pre\"; pre.textContent=content;\n  body.appendChild(pre);\n  mkBtn(\"Copier\",()=>agtCopyText(content));\n}\n\n/* --- fiche utilisateur (user.md) ---------------------------------------\n   Seul fichier que l'utilisateur peut modifier dans son interface :\n   crayon pour éditer (nom, e-mail, âge, métier, infos, instructions),\n   ✕ annule, ✓ enregistre. Protégé côté VM : recréé s'il est supprimé. */\nfunction agtB64Utf8(s){\n  /* Encodage UTF-8 → b64 sans TextEncoder (compatible partout, y c. jsdom). */\n  s=String(s==null?\"\":s);\n  let bin=\"\";\n  for(let i=0;i<s.length;i++){\n    let c=s.charCodeAt(i);\n    if(c<0x80){ bin+=String.fromCharCode(c); }\n    else if(c<0x800){ bin+=String.fromCharCode(0xc0|(c>>6),0x80|(c&63)); }\n    else if(c>=0xd800&&c<0xdc00&&i+1<s.length){\n      const cp=0x10000+((c-0xd800)<<10)+(s.charCodeAt(++i)-0xdc00);\n      bin+=String.fromCharCode(0xf0|(cp>>18),0x80|((cp>>12)&63),0x80|((cp>>6)&63),0x80|(cp&63));\n    }\n    else{ bin+=String.fromCharCode(0xe0|(c>>12),0x80|((c>>6)&63),0x80|(c&63)); }\n  }\n  return btoa(bin);\n}\nfunction agtDecodeUtf8(b64){\n  /* base64 -> texte UTF-8, sans TextDecoder (compatible jsdom). */\n  let bin=\"\";\n  try{ bin=atob(String(b64||\"\").replace(/[^A-Za-z0-9+/=]/g,\"\")); }catch(e){ return \"\"; }\n  let out=\"\", i=0;\n  while(i<bin.length){\n    const c=bin.charCodeAt(i++);\n    if(c<0x80){ out+=String.fromCharCode(c); continue; }\n    if(c<0xe0){ out+=String.fromCharCode(((c&31)<<6)|(bin.charCodeAt(i++)&63)); continue; }\n    if(c<0xf0){ out+=String.fromCharCode(((c&15)<<12)|((bin.charCodeAt(i++)&63)<<6)|(bin.charCodeAt(i++)&63)); continue; }\n    const cp=((c&7)<<18)|((bin.charCodeAt(i++)&63)<<12)|((bin.charCodeAt(i++)&63)<<6)|(bin.charCodeAt(i++)&63);\n    const v=cp-0x10000;\n    out+=String.fromCharCode(0xd800+(v>>10),0xdc00+(v&1023));\n  }\n  return out;\n}\nconst AGT_UM_HINT_INFOS=\"(Écrivez ici ce que vous voulez que l'agent sache sur vous : préférences, habitudes, projets en cours.)\";\nconst AGT_UM_HINT_INSTR=\"(Vos instructions personnelles pour l'agent : ton, format, ce qu'il doit toujours faire ou ne jamais faire.)\";\nfunction agtParseUserMd(c){\n  c=String(c==null?\"\":c);\n  const field=(label)=>{\n    const m=c.match(new RegExp(\"\\\\*\\\\*\"+label+\"\\\\s*:\\\\*\\\\*\\\\s*(.*)\",\"m\"));\n    let v=m?String(m[1]||\"\").trim():\"\";\n    if(v===\"(non renseigné)\") v=\"\";\n    return v;\n  };\n  const zone=(head)=>{\n    const i=c.indexOf(\"## \"+head);\n    if(i<0) return \"\";\n    let s=c.slice(i+head.length+3);\n    const j=s.indexOf(\"\\n## \");\n    if(j>=0) s=s.slice(0,j);\n    s=s.replace(/^\\s+/,\"\").replace(/\\s+$/,\"\");\n    if(/^\\([\\s\\S]*\\)$/.test(s)) s=\"\";   /* indice par défaut entre parenthèses */\n    return s;\n  };\n  return {nom:field(\"Nom\"),email:field(\"Adresse e-mail\"),age:field(\"Âge\"),metier:field(\"Métier\"),\n          infos:zone(\"Informations supplémentaires\"),instructions:zone(\"Instructions personnalisées\")};\n}\nfunction agtBuildUserMd(f){\n  const fl=(l,v)=>\"- **\"+l+\" :** \"+(String(v==null?\"\":v).trim()||\"(non renseigné)\");\n  return \"# user.md — Fiche utilisateur\\n\\n\"\n    +fl(\"Nom\",f.nom)+\"\\n\"+fl(\"Adresse e-mail\",f.email)+\"\\n\"+fl(\"Âge\",f.age)+\"\\n\"+fl(\"Métier\",f.metier)+\"\\n\\n\"\n    +\"## Informations supplémentaires\\n\\n\"+(String(f.infos||\"\").trim()||AGT_UM_HINT_INFOS)+\"\\n\\n\"\n    +\"## Instructions personnalisées\\n\\n\"+(String(f.instructions||\"\").trim()||AGT_UM_HINT_INSTR)+\"\\n\";\n}\nasync function agtSaveUserMd(text){\n  try{\n    const b64=agtB64Utf8(text);\n    const r=await fetch(API_BASE+\"/api/agent/exec\",{\n      method:\"POST\",headers:agtHeaders({\"Content-Type\":\"application/json\"}),\n      body:JSON.stringify({command:\"printf '%s' '\"+b64+\"'\"\n        +\" | base64 -d > /home/kasm-user/user/user.md\"\n        +\" && cp -f /home/kasm-user/user/user.md /home/kasm-user/.user.md.bak && echo SAVED\"})\n    });\n    const j=await r.json();\n    return String(j.stdout||\"\").includes(\"SAVED\");\n  }catch(e){ return false; }\n}\nfunction agtRenderUserMd(content){\n  const body=document.getElementById(\"avBody\");\n  const bar=document.getElementById(\"avBtns\");\n  const SV_PENCIL='<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 3a2.83 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z\"/><path d=\"M15 5l4 4\"/></svg>';\n  const SV_CROSS='<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M5 5l14 14M19 5L5 19\"/></svg>';\n  const SV_CHECK='<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6L9 17l-5-5\"/></svg>';\n  let cur=String(content==null?\"\":content);\n  const iconBtn=(svg,label,fn)=>{\n    const b=document.createElement(\"button\");\n    b.type=\"button\"; b.className=\"av-btn um-ico\";\n    b.setAttribute(\"aria-label\",label); b.title=label;\n    b.innerHTML=svg;\n    b.addEventListener(\"click\",()=>{ fn(b); });\n    bar.appendChild(b);\n    return b;\n  };\n  const showView=()=>{\n    bar.innerHTML=\"\";\n    iconBtn(SV_PENCIL,\"Modifier\",()=>startEdit());\n    const wrap=document.createElement(\"div\"); wrap.className=\"um-wrap\";\n    const div=document.createElement(\"div\"); div.className=\"av-md\";\n    div.innerHTML=renderMarkdown(cur);\n    wrap.appendChild(div);\n    body.innerHTML=\"\"; body.appendChild(wrap);\n  };\n  const startEdit=()=>{\n    const f=agtParseUserMd(cur);\n    bar.innerHTML=\"\";\n    iconBtn(SV_CROSS,\"Annuler\",()=>showView());\n    iconBtn(SV_CHECK,\"Enregistrer\",(b)=>save(b));\n    const wrap=document.createElement(\"div\"); wrap.className=\"um-wrap\";\n    const mkField=(label,val,ph)=>{\n      const lab=document.createElement(\"label\"); lab.className=\"um-field\";\n      const s=document.createElement(\"span\"); s.textContent=label;\n      const i=document.createElement(\"input\"); i.type=\"text\"; i.value=val||\"\"; i.placeholder=ph||\"\";\n      lab.appendChild(s); lab.appendChild(i);\n      wrap.appendChild(lab);\n      return i;\n    };\n    const mkArea=(label,val,ph)=>{\n      const lab=document.createElement(\"label\"); lab.className=\"um-field um-area\";\n      const s=document.createElement(\"span\"); s.textContent=label;\n      const ta=document.createElement(\"textarea\"); ta.className=\"um-edit\"; ta.value=val||\"\"; ta.placeholder=ph||\"\";\n      lab.appendChild(s); lab.appendChild(ta);\n      wrap.appendChild(lab);\n      return ta;\n    };\n    const F={};\n    F.inNom=mkField(\"Nom\",f.nom,\"Votre nom\");\n    F.inMail=mkField(\"Adresse e-mail\",f.email,\"vous@exemple.com\");\n    F.inAge=mkField(\"Âge\",f.age,\"ex. : 34\");\n    F.inMet=mkField(\"Métier\",f.metier,\"ex. : développeur\");\n    F.taInf=mkArea(\"Informations supplémentaires\",f.infos,\"Préférences, habitudes, projets…\");\n    F.taIns=mkArea(\"Instructions personnalisées\",f.instructions,\"Vos instructions pour l'agent…\");\n    wrap._fields=F;\n    body.innerHTML=\"\"; body.appendChild(wrap);\n    try{ F.inNom.focus(); }catch(e){}\n  };\n  const save=async(b)=>{\n    const w=body.querySelector(\".um-wrap\");\n    if(!w||!w._fields){ showView(); return; }\n    const F=w._fields;\n    const nc=agtBuildUserMd({nom:F.inNom.value,email:F.inMail.value,age:F.inAge.value,\n      metier:F.inMet.value,infos:F.taInf.value,instructions:F.taIns.value});\n    b.disabled=true;\n    const ok=await agtSaveUserMd(nc);\n    b.disabled=false;\n    if(ok){\n      cur=nc;\n      agtToast(\"Fiche enregistrée.\");\n      showView();\n      try{ agtLoadDir(AGENT_USER, document.getElementById(\"agentTree\"), 0, true); }catch(e){}\n    }else{\n      agtToast(\"Enregistrement impossible (VM injoignable).\");\n    }\n  };\n  showView();\n}\n\n\ndocument.addEventListener(\"keydown\",e=>{\n  if(e.key!==\"Escape\") return;\n  if(!agtViewer.hidden){ agtCloseViewer(); return; }\n  if(!agtPanel.hidden){ agtClosePanel(); }\n});\n\n/* --- rendu des missions : UN SEUL chemin de construction du DOM -------\n   Les mêmes fonctions servent PENDANT la mission et au RECHARGEMENT :\n   l'affichage d'une discussion est donc rigoureusement identique dans les\n   deux cas (zone terminal repliable comprise). */\nfunction agtTermEl(bubble, beforeEl, folded){\n  const term=document.createElement(\"div\"); term.className=\"agent-term\";\n  const head=document.createElement(\"div\"); head.className=\"agent-loghead\";\n  head.innerHTML='<svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg><span>Terminal de la VM</span>';\n  head.addEventListener(\"click\",()=>term.classList.toggle(\"folded\"));\n  const log=document.createElement(\"div\"); log.className=\"agent-log\";\n  term.appendChild(head); term.appendChild(log);\n  if(folded) term.classList.add(\"folded\");\n  if(beforeEl && beforeEl.parentNode===bubble) bubble.insertBefore(term, beforeEl);\n  else bubble.appendChild(term);\n  return {term:term, log:log};\n}\nfunction agtStepEl(logEl, cmd){\n  const st=document.createElement(\"div\"); st.className=\"agent-step\";\n  st.textContent=\"$ \"+String(cmd==null?\"\":cmd);\n  logEl.appendChild(st);\n  return st;\n}\nfunction agtOutEl(logEl, so, se, exit){\n  const ol=document.createElement(\"div\"); ol.className=\"agent-out\";\n  ol.textContent=(so||se||\"(aucune sortie)\")+(exit?\"  [exit \"+exit+\"]\":\"\");\n  logEl.appendChild(ol);\n  logEl.scrollTop=logEl.scrollHeight;\n  return ol;\n}\n/* Version markdown (bouton Copier) : texte final + trace du terminal. */\nfunction agtTraceMd(steps, finalText){\n  const tr=(steps||[]).map(s=>\"$ \"+s.cmd+\"\\n\"+(s.out||s.err||\"(aucune sortie)\")\n    +(s.exit?\"  [exit \"+s.exit+\"]\":\"\")).join(\"\\n\\n\");\n  return String(finalText||\"\")+(tr.trim()\n    ? (\"\\n\\n---\\n\\n**Terminal de cette mission :**\\n\\n```\\n\"+tr.trim()+\"\\n```\")\n    : \"\");\n}\n/* Mission rechargée depuis Firestore : même bulle, même zone repliable. */\nfunction agtRenderMission(bubble, steps, finalText, folded){\n  const built=agtTermEl(bubble, null, folded!==false);\n  (steps||[]).forEach(s=>{ agtStepEl(built.log, s.cmd); agtOutEl(built.log, s.out, s.err, s.exit); });\n  const finalEl=document.createElement(\"div\");\n  finalEl.className=\"agent-final\";\n  finalEl.innerHTML=(finalText&&String(finalText).trim())\n    ? renderMarkdown(String(finalText))\n    : '<p style=\"color:var(--ink-3)\"><em>(mission sans texte final)</em></p>';\n  bubble.appendChild(finalEl);\n  return built;\n}\n\n/* --- boucle d'agent : JSON ⇄ bash --- */\nfunction agtParseCall(s){\n  s=String(s||\"\");\n  const cand=[];\n  const fences=s.match(/```(?:json)?\\s*([\\s\\S]*?)```/g);\n  if(fences) fences.forEach(f=>cand.push(f.replace(/^```(?:json)?/,\"\").replace(/```$/,\"\").trim()));\n  const i=s.indexOf(\"{\");\n  if(i>=0){\n    const k=s.lastIndexOf(\"}\");\n    if(k>i) cand.push(s.slice(i,k+1));\n  }\n  for(const c of cand){\n    try{\n      const o=JSON.parse(c);\n      if(o&&typeof o===\"object\"&&(o.action||o.command)) return o;\n    }catch(e){}\n  }\n  return null;\n}\nfunction agtTrunc(s,n){\n  s=String(s==null?\"\":s);\n  return s.length>n ? s.slice(0,n)+\"\\n… [sortie tronquée]\" : s;\n}\nfunction agtNearBottom(){\n  const m=document.querySelector(\"main\");\n  return m.scrollHeight-m.scrollTop-m.clientHeight<160;\n}\nfunction agtSmart(){ if(agtNearBottom()) scrollDown(); }\n\nasync function agentRun(text){\n  if(AGENT_BUSY) return;\n  if(!agtLogged()){ agtToast(\"Veuillez vous connecter pour utiliser le mode agent.\"); return; }\n  AGENT_BUSY=true; busy=true; sendBtn.disabled=true;\n  let bubble=null;\n  try{\n    const shot=(typeof pendingImage!==\"undefined\"&&pendingImage&&pendingImage.b64)?pendingImage:null;\n    addUser(text,\"none\",null,null);\n    bubble=addAssistant();\n    promptEl.value=\"\"; promptEl.style.height=\"auto\"; scrollDown();\n    if(shot){\n      try{ pendingFiles=[]; pendingAudio=null; syncMirrors(); renderPending(); }catch(e){}\n    }\n    const finalEl=document.createElement(\"div\");\n    finalEl.className=\"agent-final\";\n    bubble.appendChild(finalEl);          /* invisible tant que vide */\n    let term=null, logEl=null;\n    const killWait=()=>{ const g=bubble.querySelector(\".gentxt\"); if(g) g.remove(); };\n    const ensureTerm=()=>{\n      if(!term){\n        killWait();\n        const built=agtTermEl(bubble, finalEl, false);\n        term=built.term; logEl=built.log;\n      }\n      return logEl;\n    };\n\n    /* Les deux fichiers de la VM sont récupérés UNE fois et envoyés dans le\n       premier message ; l'IA peut les relire elle-même à tout moment. */\n    if(AGENT_MD===null){\n      try{\n        const r=await fetch(API_BASE+\"/api/agent/file?path=\"+encodeURIComponent(AGENT_USER+\"/agent.md\"),{headers:agtHeaders()});\n        const j=await r.json();\n        AGENT_MD=j.ok?String(j.content||\"\"):\"\";\n      }catch(e){ AGENT_MD=\"\"; }\n    }\n    if(AGENT_INFOS===null){\n      try{\n        const r=await fetch(API_BASE+\"/api/agent/file?path=\"+encodeURIComponent(AGENT_USER+\"/infos.md\"),{headers:agtHeaders()});\n        const j=await r.json();\n        AGENT_INFOS=j.ok?String(j.content||\"\"):\"\";\n      }catch(e){ AGENT_INFOS=\"\"; }\n    }\n\n    const intro=[\n      \"Tu es un agent IA capable de piloter une VM Ubuntu 22.04 (Docker, bureau KASM) via son terminal.\",\n      \"\",\n      \"Voici le fichier agent.md contenant toutes tes instructions système :\",\n      AGENT_MD||\"(agent.md indisponible)\",\n      \"\",\n      \"Et voici le contenu du fichier infos.md, qui détaille ce que l'utilisateur peut faire et voit sur son interface :\",\n      AGENT_INFOS||\"(infos.md indisponible)\",\n      \"\",\n      \"Tu peux relire ces fichiers à tout moment (cat /home/kasm-user/user/agent.md, cat /home/kasm-user/user/infos.md) pour aider l'utilisateur ou le comprendre.\",\n      shot?\"Une capture d'écran actuelle de la VM est jointe à ce message.\":\"\"\n    ].join(\"\\n\");\n\n    const rappel='Tu es l\\'agent VM. Réponds par un seul objet JSON : {\"action\":\"bash\",\"command\":...} ou {\"action\":\"final\",\"message\":...}.';\n\n    /* Mémoire de la conversation : les échanges précédents sont transmis\n       à l'agent (borné pour rester léger). */\n    const hist=(typeof conv!==\"undefined\"&&conv.length)\n      ? conv.slice(-12).map(m=>\"[\"+(m.role===\"user\"?\"utilisateur\":\"assistant\")+\"] \"\n          +agtTrunc(String(m.text||\"\"),400)).join(\"\\n\")\n      : \"\";\n\n    let tr=\"\", steps=0, done=false, lastRaw=\"\", traceMd=\"\";\n    const stepsArr=[];                    /* étapes structurées (Firestore) */\n    while(steps<1000&&!done){   /* filet de sécurité très large, pas une limite pratique */\n      const prompt=steps===0\n        ? intro\n          +(hist?\"\\n\\n## Conversation précédente (contexte)\\n\"+hist:\"\")\n          +\"\\n\\nVoici le premier message de l'utilisateur :\\n\"+text\n        : rappel\n          +(hist?\"\\n\\n## Conversation précédente (contexte)\\n\"+hist:\"\")\n          +\"\\n\\n## Mission\\n\"+text\n          +(tr?\"\\n\\n## Historique des commandes\\n\"+tr:\"\")\n          +\"\\n\\nRéponds par un seul objet JSON.\";\n      const r=await fetch(API_BASE+\"/api/chat\",{\n        method:\"POST\",\n        headers:agtHeaders({\"Content-Type\":\"application/json\"}),\n        body:JSON.stringify({model:current.id,prompt,image:shot?(shot.small||shot.b64):WHITE_PX,image_kind:shot?\"upload\":\"none\",params:{temperature:0.2}})\n      });\n      let j={}; try{ j=await r.json(); }catch(e){}\n      if(!r.ok) throw new Error(j.error||(\"HTTP \"+r.status));\n      const out=String(j.output==null?\"\":j.output);\n      lastRaw=out;\n      const call=agtParseCall(out);\n      if(!call){ killWait(); finalEl.innerHTML=renderMarkdown(out); done=true; break; }\n      if(call.action===\"final\"){ killWait(); finalEl.innerHTML=renderMarkdown(String(call.message||\"\")); done=true; break; }\n      if(call.action===\"bash\"){\n        const L=ensureTerm();\n        const cmd=String(call.command||\"\");\n        agtStepEl(L,cmd);\n        agtSmart();\n        let res={};\n        try{\n          const er=await fetch(API_BASE+\"/api/agent/exec\",{\n            method:\"POST\",\n            headers:agtHeaders({\"Content-Type\":\"application/json\"}),\n            body:JSON.stringify({command:cmd})\n          });\n          res=await er.json();\n        }catch(e){ res={ok:false,stderr:String(e&&e.message||e)}; }\n        const so=agtTrunc(res.stdout||\"\",6000);\n        const se=agtTrunc(res.stderr||\"\",1500);\n        agtOutEl(L,so,se,res.exit_code);\n        stepsArr.push({cmd:cmd, out:so, err:se, exit:res.exit_code||0});\n        tr+=\"\\n[commande] \"+cmd\n          +\"\\n[exit] \"+(res.exit_code==null?\"?\":res.exit_code)\n          +\"\\n[stdout]\\n\"+so+(se?\"\\n[stderr]\\n\"+se:\"\")+\"\\n\";\n        traceMd+=\"$ \"+cmd+\"\\n\"+(so||se||\"(aucune sortie)\")\n          +(res.exit_code?\"  [exit \"+res.exit_code+\"]\":\"\")+\"\\n\\n\";\n        agtSmart();\n      }else{\n        killWait(); finalEl.innerHTML=renderMarkdown(out);\n        done=true;\n      }\n      steps++;\n    }\n    if(!done){\n      killWait();\n      finalEl.innerHTML='<p><em>(Mission interrompue : trop d\\'étapes d\\'affilée)</em></p>'+(lastRaw?renderMarkdown(lastRaw):\"\");\n    }\n    if(term) term.classList.add(\"folded\");      /* zone terminal repliée en fin de mission */\n    killWait();\n    const finalText=String(finalEl.textContent||\"(mission agent)\");\n    /* Les étapes sont enregistrées EN CLAIR dans Firestore : en rouvrant la\n       discussion (3 h plus tard, sur un autre appareil) la zone terminal\n       repliable est reconstruite à l'identique. */\n    const savedText=agtTraceMd(stepsArr, finalText);\n    conv.push({role:\"user\",text});\n    conv.push({role:\"assistant\",text:finalText});\n    msgActions(bubble,{getMd:()=>savedText});   /* bouton copier uniquement */\n    if(typeof FB!==\"undefined\"&&FB.afterAgent){\n      try{ FB.afterAgent({userText:text, steps:stepsArr, out:finalText}); }catch(e){}\n    }\n  }catch(err){\n    const b=bubble||addAssistant();\n    const g=b.querySelector(\".gentxt\"); if(g) g.remove();\n    b.innerHTML='<div class=\"err\">'+esc(String(err&&err.message?err.message:err))+'</div>';\n  }finally{\n    busy=false; sendBtn.disabled=false; AGENT_BUSY=false; agtSmart();\n  }\n}\n</script>\n</body>\n</html>\n";
/*APP_HTML_END*/

/* ---- Garde-fou agent.md / infos.md (cron + endpoint de restauration).
   Contenu canonique embarqué en base64 ; réécrit dans la VM si manquant. ---- */
const AGENT_DOC_B64 = "";
const INFOS_DOC_B64 = "";
const USER_DOC_B64 = "";
async function vmExecCmd(env, command) {
  const rq = new Request("https://vmai.hugdu77777.workers.dev/api/linux/exec", {
    method: "POST",
    headers: { "Authorization": "Bearer " + (env.VMAI_PASS || ""), "Content-Type": "application/json" },
    body: JSON.stringify({ command, timeout: 60 }),
  });
  const r = env.VMAI && typeof env.VMAI.fetch === "function" ? await env.VMAI.fetch(rq) : await fetch(rq);
  try { return await r.json(); } catch { return {}; }
}
async function ensureAgentDocs(env) {
  const out = { restored: [], present: [] };
  const chk = await vmExecCmd(env,
    'for f in agent.md infos.md user.md; do if [ -s /home/kasm-user/user/$f ]; then echo "OK:$f"; else echo "MISSING:$f"; fi; done');
  const so = String(chk.stdout || "");
  const docs = { "agent.md": AGENT_DOC_B64, "infos.md": INFOS_DOC_B64 };
  for (const name of Object.keys(docs)) {
    if (so.includes("MISSING:" + name)) {
      await vmExecCmd(env,
        "mkdir -p /home/kasm-user/user && printf '%s' '" + docs[name] + "' | base64 -d > /home/kasm-user/user/" + name);
      out.restored.push(name);
    } else if (so.includes("OK:" + name)) {
      out.present.push(name);
    }
  }
  /* user.md : fiche de l'utilisateur — restaurée depuis sa sauvegarde si
     possible, sinon depuis le modèle par défaut. Jamais écrasée si présente. */
  if (so.includes("MISSING:user.md")) {
    await vmExecCmd(env,
      "mkdir -p /home/kasm-user/user && if [ -s /home/kasm-user/.user.md.bak ]; then cp -f /home/kasm-user/.user.md.bak /home/kasm-user/user/user.md; else printf '%s' '" + USER_DOC_B64 + "' | base64 -d > /home/kasm-user/user/user.md; fi");
    out.restored.push("user.md");
  } else if (so.includes("OK:user.md")) {
    out.present.push("user.md");
  }
  return out;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type, X-Access-Code",
          "Access-Control-Max-Age": "86400",
        },
      });
    }

    /* --- Relais WebSocket vers l'API Gemini Live (la clé Google reste ici) --- */
    if (url.pathname === "/api/live") {
      if (env.ACCESS_CODE && url.searchParams.get("code") !== env.ACCESS_CODE) {
        return new Response("code d'accès invalide", { status: 401 });
      }
      const pair = new WebSocketPair();
      const clientWs = pair[0], serverWs = pair[1];
      serverWs.accept();
      const ver = url.searchParams.get("v") === "v1alpha" ? "v1alpha" : "v1beta";
      const gWs = new WebSocket(`wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.${ver}.GenerativeService.BidiGenerateContent?key=` + env.GOOGLE_API_KEY);
      const queue = [];
      let gOpen = false;
      const closeBoth = () => { try { gWs.close(); } catch (e) {} try { serverWs.close(); } catch (e) {} };
      gWs.addEventListener("open", () => {
        gOpen = true;
        while (queue.length) { try { gWs.send(queue.shift()); } catch (e) {} }
      });
      gWs.addEventListener("message", ev => { try { serverWs.send(ev.data); } catch (e) {} });
      gWs.addEventListener("close", closeBoth);
      gWs.addEventListener("error", closeBoth);
      serverWs.addEventListener("message", ev => {
        if (gOpen) { try { gWs.send(ev.data); } catch (e) {} }
        else queue.push(ev.data);
      });
      serverWs.addEventListener("close", () => { try { gWs.close(); } catch (e) {} });
      return new Response(null, { status: 101, webSocket: clientWs });
    }

    if (url.pathname === "/api/models") {
      return json({ models: Object.keys(MODELS), image_models: [...Object.keys(IMG_MODELS), ...Object.keys(HF_IMG_MODELS)] });
    }

    /* ---- génération d'image (Cloudflare Workers AI) ------------------ */
    if (url.pathname === "/api/image" && request.method === "POST") {
      if (env.ACCESS_CODE && request.headers.get("X-Access-Code") !== env.ACCESS_CODE) {
        return json({ error: "code d'accès invalide" }, 401);
      }
      if (!env.CLOUDFLARE_AI_TOKEN) {
        return json({ error: "secret CLOUDFLARE_AI_TOKEN manquant côté Worker" }, 500);
      }
      let ib;
      try {
        ib = await request.json();
      } catch {
        return json({ error: "corps JSON invalide" }, 400);
      }
      if (HF_IMG_MODELS[ib.model]) return await hfImage(HF_IMG_MODELS[ib.model], ib);
      if (POLL_IMG_MAP[ib.model]) {
        if (!env.POLLINATIONS_API_KEY) return json({ error: "secret POLLINATIONS_API_KEY manquant côté Worker" }, 500);
        const p = ib.params && typeof ib.params === "object" ? ib.params : {};
        /* contraintes MAI : multiples de 16, 768 px min par côté, 1 048 576 px² max */
        const q16 = (v) => { const n = Math.round(Number(v) / 16) * 16; return Math.min(1024, Math.max(768, Number.isFinite(n) && n > 0 ? n : 1024)); };
        const editB64 = String(ib.image || "");
        if (editB64) {   /* toute image jointe => édition (si modèle Pollinations) */
          /* Édition d'image : l'utilisateur a joint une image existante à modifier. */
          const fd = new FormData();
          fd.append("model", POLL_IMG_MAP[ib.model]);
          fd.append("prompt", String(ib.prompt || ""));
          fd.append("size", q16(p.width || 1024) + "x" + q16(p.height || 1024));
          fd.append("image", new Blob([b64ToBytes(editB64)], { type: "image/png" }), "image.png");
          let ue;
          try {
            ue = await fetch(POLL_URL + "/v1/images/edits", {
              method: "POST",
              headers: { Authorization: "Bearer " + env.POLLINATIONS_API_KEY },
              body: fd,
            });
          } catch (err) { return json({ error: "Pollinations injoignable (édition) : " + err.message }, 502); }
          const te = await ue.text();
          let je; try { je = JSON.parse(te); } catch { je = null; }
          if (!ue.ok) return json({ error: pollErrorMessage(ue.status, te) }, (ue.status === 402 || ue.status === 429 || ue.status === 503) ? ue.status : 502);
          const be = je && je.data && je.data[0] && je.data[0].b64_json;
          if (!be) return json({ error: "aucune image dans la réponse Pollinations (édition)" }, 502);
          return json({ image: be, mime: detectMime(be) });
        }
        const qb = { model: POLL_IMG_MAP[ib.model], prompt: String(ib.prompt || ""), size: q16(p.width || 1024) + "x" + q16(p.height || 1024), response_format: "b64_json" };
        if (p.quality) qb.quality = String(p.quality);
        let up;
        try {
          up = await fetch(POLL_URL + "/v1/images/generations", {
            method: "POST",
            headers: { "Content-Type": "application/json", Authorization: "Bearer " + env.POLLINATIONS_API_KEY },
            body: JSON.stringify(qb),
          });
        } catch (err) { return json({ error: "Pollinations injoignable : " + err.message }, 502); }
        const t = await up.text();
        let j3; try { j3 = JSON.parse(t); } catch { j3 = null; }
        if (!up.ok) return json({ error: pollErrorMessage(up.status, t) }, (up.status === 402 || up.status === 429 || up.status === 503) ? up.status : 502);
        const b64 = j3 && j3.data && j3.data[0] && j3.data[0].b64_json;
        if (!b64) return json({ error: "aucune image dans la réponse Pollinations" }, 502);
        return json({ image: b64, mime: detectMime(b64) });
      }
      const slug = IMG_MODELS[ib.model];
      if (!slug) return json({ error: `modèle d'image inconnu : ${String(ib.model)}` }, 400);
      const iprompt = String(ib.prompt ?? "").trim();
      if (!iprompt) return json({ error: "prompt vide" }, 400);
      if (iprompt.length > 4000) return json({ error: "prompt trop long (max 4000 caractères)" }, 400);

      const fd = new FormData();
      fd.append("prompt", iprompt);
      const ip = ib.params && typeof ib.params === "object" ? ib.params : {};
      const iw = int(ip.width, 256, 2048);
      const ih = int(ip.height, 256, 2048);
      const isteps = int(ip.num_steps, 1, 50);
      const ig = num(ip.guidance, 0, 10);
      if (iw !== undefined) fd.append("width", String(iw));
      if (ih !== undefined) fd.append("height", String(ih));
      if (isteps !== undefined) fd.append("num_steps", String(isteps));
      if (ig !== undefined) fd.append("guidance", String(ig));

      let iup;
      try {
        iup = await fetch(`https://api.cloudflare.com/client/v4/accounts/${CF_ACCOUNT_ID}/ai/run/@cf/${slug}`, {
          method: "POST",
          headers: { Authorization: `Bearer ${env.CLOUDFLARE_AI_TOKEN}` },
          body: fd,
        });
      } catch (err) {
        return json({ error: `Cloudflare AI injoignable : ${err.message}` }, 502);
      }
      const itext = await iup.text();
      if (!iup.ok) {
        let imsg = itext.slice(0, 400);
        try {
          const id = JSON.parse(itext);
          if (id.errors && id.errors[0] && id.errors[0].message) imsg = id.errors[0].message;
        } catch { /* on garde le texte brut */ }
        return json({ error: `Cloudflare AI HTTP ${iup.status} — ${imsg}` }, iup.status === 429 ? 429 : 502);
      }
      let idata;
      try {
        idata = JSON.parse(itext);
      } catch {
        return json({ error: "réponse Cloudflare AI invalide" }, 502);
      }
      const iimg = idata && idata.result ? idata.result.image : null;
      if (!iimg) return json({ error: "aucune image dans la réponse Cloudflare AI" }, 502);
      return json({ image: iimg, mime: (idata.result && idata.result.mime) || "image/jpeg" });
    }

    /* --- Streaming SSE (modèles texte Groq et Google) --- */
    if (url.pathname === "/api/chat/stream" && request.method === "POST") {
      if (env.ACCESS_CODE && request.headers.get("X-Access-Code") !== env.ACCESS_CODE) {
        return json({ error: "code d'accès invalide" }, 401);
      }
      let body;
      try { body = await request.json(); } catch { return json({ error: "corps JSON invalide" }, 400); }
      const model = body.model;
      const prompt = String(body.prompt ?? "").trim();
      if (!prompt) return json({ error: "prompt vide" }, 400);
      const params = body.params && typeof body.params === "object" ? body.params : {};
      const isGroq = !!GROQ_MAP[model];
      const isPoll = !!POLL_TEXT_MAP[model];
      const gcfg = GOOGLE_MAP[model];
      if (!isGroq && !isPoll && !(gcfg && !gcfg.kind)) return json({ error: "streaming non supporté pour ce modèle" }, 400);

      let up;
      try {
        if (isGroq) {
          const gq = { model: GROQ_MAP[model], messages: [{ role: "user", content: prompt }], stream: true };
          if (params.temperature !== undefined && params.temperature !== null && params.temperature !== "") gq.temperature = Number(params.temperature);
          if (params.top_p) gq.top_p = Number(params.top_p);
          if (params.reasoning_effort) gq.reasoning_effort = String(params.reasoning_effort);
          const baseMax = params.max_tokens ? Math.max(1, Number(params.max_tokens) || 1024) : (GROQ_MAXOUT[model] || 4096);
          const steps = [baseMax];
          for (const s of GROQ_RETRY_MAX) if (s < baseMax) steps.push(s);
          for (let i = 0; i < steps.length; i++) {
            gq.max_completion_tokens = steps[i];
            const r = await fetch("https://api.groq.com/openai/v1/chat/completions", {
              method: "POST",
              headers: { "Content-Type": "application/json", Authorization: "Bearer " + env.GROQ_API_KEY, "User-Agent": BROWSER_UA },
              body: JSON.stringify(gq),
            });
            if (r.status === 429) {
              const te = await r.text();
              if (GROQ_TOO_LARGE_RE.test(te) && i < steps.length - 1) continue;
              return json({ error: groqApiError(429, te) }, 429);
            }
            up = r;
            break;
          }
        } else if (isPoll) {
          const parts = [];
          for (const im of normImageList(body)) {
            parts.push({ type: "text", text: "[image « " + im.name + " »]" });
            parts.push({ type: "image_url", image_url: { url: dataUri(im) } });
          }
          parts.push({ type: "text", text: prompt });
          const rq = { model: POLL_TEXT_MAP[model], messages: [{ role: "user", content: parts }], stream: true };
          if (params.max_tokens) rq.max_tokens = Math.max(1, Number(params.max_tokens) || 1024);
          if (params.temperature !== undefined && params.temperature !== null && params.temperature !== "") rq.temperature = Number(params.temperature);
          if (params.reasoning_effort) rq.reasoning_effort = String(params.reasoning_effort);
          up = await fetch(POLL_URL + "/v1/chat/completions", {
            method: "POST",
            headers: { "Content-Type": "application/json", Authorization: "Bearer " + env.POLLINATIONS_API_KEY },
            body: JSON.stringify(rq),
          });
          if (up.status === 402 || up.status === 429) {
            const te = await up.text();
            return json({ error: pollErrorMessage(up.status, te) }, up.status);
          }
        } else {
          const H = { "Content-Type": "application/json", "x-goog-api-key": env.GOOGLE_API_KEY };
          const parts = [{ text: prompt }];
          for (const im of normImageList(body)) parts.unshift({ inline_data: { mime_type: im.mime, data: im.b64 } });
          const gc = {};
          if (params.max_tokens) gc.maxOutputTokens = Number(params.max_tokens);
          if (params.temperature !== undefined && params.temperature !== null && params.temperature !== "") gc.temperature = Number(params.temperature);
          if (params.thinking_level) gc.thinkingConfig = { thinkingLevel: String(params.thinking_level) };
          const tools = [];
          if (params.google_search) tools.push({ google_search: {} });
          if (params.google_code_execution) tools.push({ code_execution: {} });
          if (params.google_url_context) tools.push({ url_context: {} });
          if (params.google_maps) tools.push({ google_maps: {} });
          const reqBody = { contents: [{ role: "user", parts }] };
          if (Object.keys(gc).length) reqBody.generationConfig = gc;
          if (tools.length) reqBody.tools = tools;
          up = await fetch("https://generativelanguage.googleapis.com/v1beta/models/" + gcfg.m + ":streamGenerateContent?alt=sse", {
            method: "POST", headers: H, body: JSON.stringify(reqBody),
          });
        }
      } catch (err) { return json({ error: "API injoignable : " + err.message }, 502); }
      if (!up.ok) {
        const t = await up.text();
        if (isGroq) return json({ error: groqApiError(up.status, t) }, (up.status === 413 || up.status === 429) ? up.status : 502);
        if (isPoll) return json({ error: pollErrorMessage(up.status, t) }, (up.status === 402 || up.status === 429) ? up.status : 502);
        return json({ error: "Google HTTP " + up.status + " — " + t.slice(0, 200) }, 502);
      }
      const enc = new TextEncoder();
      /* Pour Pollinations : lit la tête du flux avant de le relayer ; si le
         message « crédits » apparaît, répond 402 (bascule Roboflow côté app). */
      const reader = up.body.getReader();
      const dec0 = new TextDecoder();
      const preBuf = [];
      let preText = "", rawLeft = "";
      if (isPoll) {
        const t0 = Date.now();
        while (preText.length < 300 && Date.now() - t0 < 1500) {
          const r1 = await reader.read();
          if (r1.done) break;
          rawLeft += dec0.decode(r1.value, { stream: true });
          let ix;
          while ((ix = rawLeft.indexOf("\n")) >= 0) {
            const line = rawLeft.slice(0, ix).trim();
            rawLeft = rawLeft.slice(ix + 1);
            if (!line.startsWith("data:")) continue;
            const payload = line.slice(5).trim();
            if (payload === "[DONE]") continue;
            let j1; try { j1 = JSON.parse(payload); } catch { continue; }
            const d1 = j1.choices && j1.choices[0] && j1.choices[0].delta && j1.choices[0].delta.content;
            if (d1) { preText += d1; preBuf.push({ t: d1 }); }
          }
          if (pollCreditText(preText)) break;
        }
        if (pollCreditText(preText)) {
          try { await reader.cancel(); } catch {}
          return json({ error: pollErrorMessage(402, preText) }, 402);
        }
      }
      const sse = new ReadableStream({
        async start(controller) {
          const dec = new TextDecoder();
          let buf = rawLeft;
          const send = (o) => controller.enqueue(enc.encode("data: " + JSON.stringify(o) + "\n\n"));
          for (const pb of preBuf) send(pb);
          try {
            while (true) {
              const { done, value } = await reader.read();
              if (done) break;
              buf += dec.decode(value, { stream: true });
              let idx;
              while ((idx = buf.indexOf("\n")) >= 0) {
                const line = buf.slice(0, idx).trim();
                buf = buf.slice(idx + 1);
                if (!line.startsWith("data:")) continue;
                const payload = line.slice(5).trim();
                if (payload === "[DONE]") continue;
                let j; try { j = JSON.parse(payload); } catch { continue; }
                if (isGroq || isPoll) {
                  const ch0 = j.choices && j.choices[0];
                  const d = ch0 && ch0.delta && ch0.delta.content;
                  if (d) send({ t: d });
                  if (ch0 && ch0.finish_reason === "length") send({ t: "\n\n*(réponse interrompue : limite de tokens atteinte — relancez pour continuer)*" });
                } else {
                  const ps = (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts) || [];
                  for (const p of ps) {
                    const tx = p.text || (p.audioTranscription && p.audioTranscription.text);
                    if (tx) send({ t: tx });
                  }
                }
              }
            }
          } catch (e) {
            try { send({ error: "flux interrompu : " + e.message }); } catch {}
          }
          controller.enqueue(enc.encode("data: [DONE]\n\n"));
          controller.close();
        },
      });
      return new Response(sse, {
        headers: {
          "Content-Type": "text/event-stream; charset=utf-8",
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
          "Access-Control-Allow-Headers": "Content-Type, X-Access-Code",
          "Cache-Control": "no-store",
        },
      });
    }

    if (url.pathname === "/app" || url.pathname === "/app/") {
      return new Response(APP_HTML, {
        headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
      });
    }

    /* ---- Agent : relais vers la VM (worker vmai). Le mot de passe VMAI_PASS
       reste ici, jamais exposé à l'interface. ---- */
    if (url.pathname.startsWith("/api/agent/")) {
      if (env.ACCESS_CODE && request.headers.get("X-Access-Code") !== env.ACCESS_CODE) {
        return json({ error: "code d'accès invalide" }, 401);
      }
      const VM_BASE = "https://vmai.hugdu77777.workers.dev/api/linux";
      const sub = url.pathname.slice("/api/agent/".length);
      const H = { "Authorization": "Bearer " + (env.VMAI_PASS || "") };
      const corsH = { "Access-Control-Allow-Origin": "*" };
      /* Liaison de service (VMAI) : appel worker-à-worker direct, insensible
         à l'état du sous-domaine workers.dev. Repli : fetch HTTP classique. */
      const vmFetch = (u, init) => {
        const rq = new Request(u, init);
        return env.VMAI && typeof env.VMAI.fetch === "function" ? env.VMAI.fetch(rq) : fetch(rq);
      };
      try {
        if (sub === "docs/restore") {
          const res = await ensureAgentDocs(env);
          return json(res);
        }
        if (sub === "exec" && request.method === "POST") {
          let b = {};
          try { b = await request.json(); } catch {}
          const payload = { command: String(b.command || "") };
          if (b.user === "root" || b.user === "kasm-user") payload.user = b.user;
          if (typeof b.cwd === "string") payload.cwd = b.cwd.slice(0, 300);
          if (b.timeout) payload.timeout = Math.min(Math.max(1, Number(b.timeout) || 30), 300);
          const up = await vmFetch(VM_BASE + "/exec", {
            method: "POST",
            headers: { ...H, "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          });
          return new Response(up.body, { status: up.status, headers: { "Content-Type": "application/json", ...corsH } });
        }
        if (sub === "screenshot" && request.method === "GET") {
          const up = await vmFetch(VM_BASE + "/screenshot", { headers: H });
          return new Response(up.body, { status: up.status, headers: { "Content-Type": up.headers.get("Content-Type") || "image/png", "Cache-Control": "no-store", ...corsH } });
        }
        if (sub === "files" && request.method === "GET") {
          const up = await vmFetch(VM_BASE + "/files?path=" + encodeURIComponent(url.searchParams.get("path") || "user"), { headers: H });
          return new Response(up.body, { status: up.status, headers: { "Content-Type": "application/json", ...corsH } });
        }
        if (sub === "file" && request.method === "GET") {
          const fmt = url.searchParams.get("format") === "base64" ? "base64" : "utf8";
          const up = await vmFetch(VM_BASE + "/files/read?path=" + encodeURIComponent(url.searchParams.get("path") || "") + "&format=" + fmt, { headers: H });
          return new Response(up.body, { status: up.status, headers: { "Content-Type": "application/json", ...corsH } });
        }
        return json({ error: "route agent inconnue" }, 404);
      } catch (err) {
        return json({ error: "VM injoignable : " + (err && err.message ? err.message : String(err)) }, 502);
      }
    }

    if (url.pathname !== "/api/chat" || request.method !== "POST") {
      return json({ error: "route inconnue" }, 404);
    }

    if (env.ACCESS_CODE && request.headers.get("X-Access-Code") !== env.ACCESS_CODE) {
      return json({ error: "code d'accès invalide" }, 401);
    }

    const len = Number(request.headers.get("Content-Length") || 0);
    if (len > MAX_BODY_BYTES) {
      return json({ error: `image trop lourde (${(len / 1e6).toFixed(1)} Mo, max ${MAX_BODY_BYTES / 1e6} Mo)` }, 413);
    }

    let body;
    try {
      body = await request.json();
    } catch {
      return json({ error: "corps JSON invalide" }, 400);
    }

    const model = body.model;
    const prompt = String(body.prompt ?? "").trim();
    if (!prompt) return json({ error: "prompt vide" }, 400);

    const params = body.params && typeof body.params === "object" ? body.params : {};
    const rawImage = String(body.image ?? "");

    /* --- Canal Pollinations (texte, compatible OpenAI, vision incluse) --- */
    if (POLL_TEXT_MAP[model]) {
      const parts = [];
      for (const im of normImageList(body)) {
        parts.push({ type: "text", text: "[image « " + im.name + " »]" });
        parts.push({ type: "image_url", image_url: { url: dataUri(im) } });
      }
      parts.push({ type: "text", text: prompt });
      const rq = { model: POLL_TEXT_MAP[model], messages: [{ role: "user", content: parts }] };
      if (params.max_tokens) rq.max_tokens = Math.max(1, Number(params.max_tokens) || 1024);
      if (params.temperature !== undefined && params.temperature !== null && params.temperature !== "") rq.temperature = Number(params.temperature);
      if (params.reasoning_effort) rq.reasoning_effort = String(params.reasoning_effort);
      let up;
      try {
        up = await fetch(POLL_URL + "/v1/chat/completions", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: "Bearer " + env.POLLINATIONS_API_KEY },
          body: JSON.stringify(rq),
        });
      } catch (err) { return json({ error: `Pollinations injoignable : ${err.message}` }, 502); }
      const t = await up.text();
      let pj; try { pj = JSON.parse(t); } catch { pj = null; }
      if (!up.ok) return json({ error: pollErrorMessage(up.status, t) }, (up.status === 402 || up.status === 429 || up.status === 503) ? up.status : 502);
      let out = String(pj?.choices?.[0]?.message?.content ?? "").trim();
      if (pollCreditText(out)) return json({ error: pollErrorMessage(402, out) }, 402);
      if (pj?.choices?.[0]?.finish_reason === "length") out += "\n\n*(réponse interrompue : limite de tokens atteinte — relancez pour continuer)*";
      return json({ output: out, applied: [] });
    }

    /* --- Canal Groq --- */
    if (GROQ_MAP[model]) {
      const gq = { model: GROQ_MAP[model], messages: [{ role: "user", content: prompt }] };
      if (params.temperature !== undefined && params.temperature !== null && params.temperature !== "") gq.temperature = Number(params.temperature);
      if (params.top_p) gq.top_p = Number(params.top_p);
      if (params.reasoning_effort) gq.reasoning_effort = String(params.reasoning_effort);
      const baseMax = params.max_tokens ? Math.max(1, Number(params.max_tokens) || 1024) : (GROQ_MAXOUT[model] || 4096);
      const steps = [baseMax];
      for (const s of GROQ_RETRY_MAX) if (s < baseMax) steps.push(s);
      let up = null, t = "", gj = null;
      for (let i = 0; i < steps.length; i++) {
        gq.max_completion_tokens = steps[i];
        try {
          up = await fetch("https://api.groq.com/openai/v1/chat/completions", {
            method: "POST",
            headers: { "Content-Type": "application/json", Authorization: "Bearer " + env.GROQ_API_KEY, "User-Agent": BROWSER_UA },
            body: JSON.stringify(gq),
          });
        } catch (err) { return json({ error: `Groq injoignable : ${err.message}` }, 502); }
        t = await up.text();
        if (up.status === 429) {
          if (GROQ_TOO_LARGE_RE.test(t) && i < steps.length - 1) continue;
          return json({ error: groqApiError(429, t) }, 429);
        }
        break;
      }
      try { gj = JSON.parse(t); } catch { gj = null; }
      if (!up.ok) return json({ error: groqApiError(up.status, t) }, (up.status === 413 || up.status === 429) ? up.status : 502);
      let out = String(gj?.choices?.[0]?.message?.content ?? "").trim();
      if (gj?.choices?.[0]?.finish_reason === "length") out += "\n\n*(réponse interrompue : limite de tokens atteinte — relancez pour continuer)*";
      return json({ output: out, applied: [] });
    }

    /* --- Canal Google (Gemini API) --- */
    if (GOOGLE_MAP[model]) {
      const cfg = GOOGLE_MAP[model];
      const H = { "Content-Type": "application/json", "x-goog-api-key": env.GOOGLE_API_KEY };
      const B = "https://generativelanguage.googleapis.com/v1beta/models/" + cfg.m;
      try {
        if (cfg.kind === "embed") {
          const up = await fetch(B + ":embedContent", { method: "POST", headers: H, body: JSON.stringify({ content: { parts: [{ text: prompt }] } }) });
          const j2 = await up.json().catch(() => null);
          if (!up.ok) return json({ error: `Google HTTP ${up.status} — ${j2?.error?.message || ""}` }, 502);
          const v = j2?.embedding?.values || [];
          const norm = Math.sqrt(v.reduce((a, x) => a + x * x, 0));
          return json({ output: "", embedding: { dim: v.length, head: v.slice(0, 12).map(x => +x.toFixed(5)), norm: +norm.toFixed(4) } });
        }
        const parts = [{ text: prompt }];
        const rawAudio = String(body.audio ?? "");
        if (rawAudio) parts.unshift({ inline_data: { mime_type: String(body.audio_mime || "audio/wav"), data: rawAudio } });
        if (cfg.kind !== "transcribe") for (const im of normImageList(body)) parts.unshift({ inline_data: { mime_type: im.mime, data: im.b64 } });
        const gc = {};
        if (params.max_tokens) gc.maxOutputTokens = Number(params.max_tokens);
        if (params.temperature !== undefined && params.temperature !== null && params.temperature !== "") gc.temperature = Number(params.temperature);
        if (params.thinking_level) gc.thinkingConfig = { thinkingLevel: String(params.thinking_level) };
        const tools = [];
        if (params.google_search) tools.push({ google_search: {} });
        if (params.google_code_execution) tools.push({ code_execution: {} });
        if (params.google_url_context) tools.push({ url_context: {} });
        if (params.google_maps) tools.push({ google_maps: {} });
        const reqBody = { contents: [{ role: "user", parts }] };
        if (cfg.kind === "tts") {
          gc.responseModalities = ["AUDIO"];
          gc.speechConfig = { voiceConfig: { prebuiltVoiceConfig: { voiceName: String(params.voice || "Kore") } } };
          delete gc.maxOutputTokens;
        }
        if (Object.keys(gc).length) reqBody.generationConfig = gc;
        if (tools.length) reqBody.tools = tools;
        const up = await fetch(B + ":generateContent", { method: "POST", headers: H, body: JSON.stringify(reqBody) });
        const j2 = await up.json().catch(() => null);
        if (!up.ok) return json({ error: `Google HTTP ${up.status} — ${j2?.error?.message || ""}` }, 502);
        const cand = j2?.candidates?.[0];
        const ps = cand?.content?.parts || [];
        const txt = ps.map(p => p.text || (p.audioTranscription && p.audioTranscription.text) || "").join("").trim();
        if (cfg.kind === "tts") {
          const au = ps.find(p => p.inlineData && p.inlineData.data);
          if (!au) return json({ error: "Google TTS : aucune donnée audio renvoyée" }, 502);
          return json({ output: txt, audio: au.inlineData.data, mime: au.inlineData.mimeType || "audio/wav" });
        }
        const gm = cand?.groundingMetadata;
        const applied = [...new Set((gm?.groundingChunks || []).map(c => c?.web?.uri).filter(Boolean))].slice(0, 6);
        return json({ output: txt, applied });
      } catch (err) { return json({ error: `Google injoignable : ${err.message}` }, 502); }
    }

    const spec = MODELS[model];
    if (!spec) return json({ error: `modèle inconnu : ${String(model)}` }, 400);

    // Le champ image est obligatoire côté Roboflow : le client envoie un
    // pixel blanc 1x1 par défaut, une image noire sur demande, ou une image
    // fournie.
    const image = rawImage;
    if (!image) return json({ error: "image manquante (champ obligatoire côté Roboflow)" }, 400);
    if (image.length > MAX_BODY_BYTES) {
      return json({ error: "image trop lourde après encodage base64" }, 413);
    }

    const step = {
      type: spec.block,
      name: "m",
      images: "$inputs.image",
      prompt,
      [spec.vf || "model_version"]: spec.vv || model,
      ...sanitize(body.params, spec.family),
    };
    if (!spec.nokey) step.api_key = "rf_key:account";
    if (spec.task !== null) step.task_type = spec.task || "unconstrained";
    if (spec.backend) step.backend = spec.backend;

    const payload = {
      api_key: env.ROBOFLOW_API_KEY,
      inputs: { image: { type: "base64", value: image } },
      specification: {
        version: "1.0",
        inputs: [{ type: "WorkflowImage", name: "image" }],
        steps: [step],
        outputs: [{ type: "JsonField", name: "output", selector: `$steps.m.${spec.out || "output"}` }],
      },
    };

    let upstream;
    try {
      upstream = await fetch(ROBOFLOW_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
    } catch (err) {
      return json({ error: `Roboflow injoignable : ${err.message}` }, 502);
    }

    const text = await upstream.text();
    let data;
    try {
      data = JSON.parse(text);
    } catch {
      return json({ error: `Roboflow HTTP ${upstream.status} — ${text.slice(0, 400)}` }, 502);
    }

    if (!upstream.ok) {
      const detail = data.inner_error_message || data.message || text.slice(0, 400);
      return json({ error: `Roboflow HTTP ${upstream.status} — ${detail}` }, 502);
    }

    const outputs = data.outputs && data.outputs[0] ? data.outputs[0] : {};
    return json({ output: outputs.output ?? "", applied: Object.keys(sanitize(body.params, spec.family)) });
  },

  /* ---- Cron : recrée agent.md / infos.md dans la VM s'ils ont été supprimés. ---- */
  async scheduled(controller, env, ctx) {
    ctx.waitUntil(ensureAgentDocs(env).catch(() => {}));
  },
};
